<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NairaBill · Invoices</title><style>body{margin:0;background:#f5f8f5;color:#152a24;font:14px/1.5 Inter,system-ui,sans-serif}.wrap{max-width:1200px;margin:auto;padding:28px 20px}.top{display:flex;justify-content:space-between;align-items:center;gap:12px}.brand{font-size:23px;font-weight:900}.brand span{color:#147d58}a{color:#147d58}button,.btn{background:#147d58;color:white;padding:9px 13px;border:0;border-radius:8px;text-decoration:none;font:inherit;font-weight:700;cursor:pointer}.panel{background:white;border:1px solid #e1e9e4;border-radius:14px;padding:18px;margin-top:20px;overflow:auto}.alert{padding:12px;border-radius:8px;margin-top:12px}.success{background:#e9f6ed;color:#236747}.error{background:#fff0ed;color:#a23d2d}table{border-collapse:collapse;width:100%;min-width:760px}th,td{text-align:left;padding:12px 9px;border-bottom:1px solid #edf1ee}th{font-size:11px;text-transform:uppercase;color:#6b7b74}td{font-size:13px}.pill{background:#e9f6ed;border-radius:20px;padding:4px 8px}.bad{background:#fff0ed}</style></head><body><main class="wrap"><header class="top"><div><a href="/customer/dashboard" class="brand" style="text-decoration:none;color:inherit">Naira<span>Bill</span></a><div>Invoices · <?= $esc($customer['workspace_name']) ?></div></div><div><a class="btn" href="/customer/dashboard#create-invoice">Create invoice</a> <a href="/customer/logout">Sign out</a></div></header><?php if($ok): ?><div class="alert success"><?= $esc(strip_tags((string)$ok)) ?></div><?php endif; ?><?php if($err): ?><div class="alert error"><?= $esc(strip_tags((string)$err)) ?></div><?php endif; ?><section class="panel"><table><thead><tr><th>Invoice</th><th>Customer</th><th>Email</th><th>Total</th><th>Fee payer</th><th>Status</th><th>Due</th><th>Hosted link</th></tr></thead><tbody><?php if(!$invoices): ?><tr><td colspan="8">No invoices found.</td></tr><?php endif;foreach($invoices as $i): ?><tr><td><?= $esc($i['invoice_number']) ?></td><td><?= $esc($i['customer_name']) ?></td><td><?= $esc($i['customer_email']) ?></td><td><?= $esc($i['currency']) ?> <?= number_format((float)$i['total_amount'],2) ?></td><td><?= $esc($i['fee_payer']) ?></td><td><span class="pill <?= in_array($i['status'],['cancelled','expired','refunded'])?'bad':'' ?>"><?= $esc($i['status']) ?></span></td><td><?= $esc($i['due_date']?:'—') ?></td><td><a target="_blank" rel="noopener" href="<?= $esc($i['hosted_url']?:('/pay/'.$i['public_id'])) ?>">Open</a></td></tr><?php endforeach; ?></tbody></table></section></main></body></html>
